css:
.print-format { padding: 0 !important; margin: 0 !important; max-width: 80mm; }
.gc { width: 72mm; margin: 0 auto; font-family: monospace, sans-serif; font-size: 12px; color: #000; }
.gc-c { text-align: center; }
.gc-r { text-align: right; white-space: nowrap; }
.gc-b { font-weight: bold; }
.gc-l { font-size: 15px; }
.gc-s { font-size: 10px; }
.gc-hr { border-top: 1px dashed #000; margin: 6px 0; }
.gc-t { width: 100%; border-collapse: collapse; }
.gc-t td { padding: 1px 0; vertical-align: top; }
.gc-seat { font-weight: bold; text-decoration: underline; padding-top: 4px !important; }
@page { size: 80mm auto; margin: 2mm; }

html:
{%- set seats = [] -%}
{%- for row in doc.items -%}{%- if row.posa_seat and row.posa_seat not in seats -%}{%- set _ = seats.append(row.posa_seat) -%}{%- endif -%}{%- endfor -%}
<div class="gc">
  <div class="gc-c gc-b gc-l">{{ doc.company }}</div>
  <div class="gc-c gc-b">{{ _("GUEST CHECK") }}</div>
  <div class="gc-c gc-s">{{ _("Not a tax invoice. The tax invoice is printed after payment.") }}</div>
  <div class="gc-hr"></div>
  <table class="gc-t">
    <tr><td>{{ _("Order") }}</td><td class="gc-r">{{ doc.name }}</td></tr>
    {%- if doc.posa_service_table %}<tr><td>{{ _("Table") }}</td><td class="gc-r gc-b">{{ doc.posa_service_table }}</td></tr>{% endif %}
    {%- if doc.posa_covers %}<tr><td>{{ _("Guests") }}</td><td class="gc-r">{{ doc.posa_covers }}</td></tr>{% endif %}
    <tr><td>{{ _("Server") }}</td><td class="gc-r">{{ frappe.db.get_value("User", doc.owner, "full_name") or doc.owner }}</td></tr>
    <tr><td>{{ _("Date") }}</td><td class="gc-r">{{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "dd-MM-yyyy HH:mm") }}</td></tr>
  </table>
  <div class="gc-hr"></div>
  {%- macro item_row(row) -%}
    {%- if not row.posa_parent_row_id -%}
    <tr><td colspan="2" class="gc-b">{{ row.item_name }}</td></tr>
    {%- else -%}
    <tr><td colspan="2">&nbsp;&nbsp;+ {{ row.item_name }}</td></tr>
    {%- endif -%}
    {%- if row.posa_modifiers %}<tr><td colspan="2" class="gc-s">&nbsp;&nbsp;{{ row.posa_modifiers }}</td></tr>{% endif %}
    <tr>
      <td>&nbsp;&nbsp;{{ row.qty|int if row.qty == row.qty|int else row.qty }}{% if not row.posa_comp %} x {{ frappe.utils.fmt_money(row.price_list_rate or row.rate, currency=doc.currency) }}{% endif %}</td>
      <td class="gc-r">{% if row.posa_comp %}{{ _("COMP") }}{% else %}{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}{% endif %}</td>
    </tr>
  {%- endmacro -%}
  <table class="gc-t">
  {%- if seats|length > 1 -%}
    {%- for seat in seats|sort -%}
      <tr><td colspan="2" class="gc-seat">{{ _("Seat") }} {{ seat }}</td></tr>
      {%- for row in doc.items if row.posa_seat == seat %}{{ item_row(row) }}{% endfor -%}
    {%- endfor -%}
    {%- set shared = doc.items | selectattr("posa_seat", "in", [0, None]) | list -%}
    {%- if shared %}<tr><td colspan="2" class="gc-seat">{{ _("Shared") }}</td></tr>{% for row in shared %}{{ item_row(row) }}{% endfor %}{% endif -%}
  {%- else -%}
    {%- for row in doc.items %}{{ item_row(row) }}{% endfor -%}
  {%- endif -%}
  </table>
  <div class="gc-hr"></div>
  <table class="gc-t">
    <tr><td>{{ _("Subtotal") }}</td><td class="gc-r">{{ frappe.utils.fmt_money(doc.total, currency=doc.currency) }}</td></tr>
    {%- if doc.discount_amount %}<tr><td>{{ _("Discount") }}</td><td class="gc-r">- {{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}</td></tr>{% endif %}
    {%- for tax in doc.taxes if tax.tax_amount %}<tr><td>{{ tax.description }}</td><td class="gc-r">{{ frappe.utils.fmt_money(tax.tax_amount, currency=doc.currency) }}</td></tr>{% endfor %}
    <tr class="gc-b gc-l"><td>{{ _("Total") }}</td><td class="gc-r">{{ frappe.utils.fmt_money(doc.rounded_total or doc.grand_total, currency=doc.currency) }}</td></tr>
    {%- if doc.posa_split_count and doc.posa_split_count > 1 %}
    <tr><td colspan="2" class="gc-b" style="padding-top:6px !important">{{ _("Split {0} ways").format(doc.posa_split_count) }}</td></tr>
    {%- for n in range(1, doc.posa_split_count + 1) %}<tr><td>{{ _("Share {0}").format(n) }}</td><td class="gc-r">{{ frappe.utils.fmt_money((doc.rounded_total or doc.grand_total) / doc.posa_split_count, currency=doc.currency) }}</td></tr>{% endfor %}
    {%- elif doc.posa_covers and doc.posa_covers > 1 %}<tr class="gc-s"><td>{{ _("Per guest ({0})").format(doc.posa_covers) }}</td><td class="gc-r">{{ frappe.utils.fmt_money((doc.rounded_total or doc.grand_total) / doc.posa_covers, currency=doc.currency) }}</td></tr>{% endif %}
  </table>
  <div class="gc-hr"></div>
  <div class="gc-c gc-s">{{ _("Thank you. Please let your server know when you are ready to pay.") }}</div>
  {%- set fb_qr = feedback_qr(doc.name) if feedback_qr is defined else "" -%}
  {%- if fb_qr %}
  <div class="gc-hr"></div>
  <div class="gc-c gc-s">{{ _("Tell us how we did") }}</div>
  <div class="gc-c">{{ fb_qr }}</div>
  <div class="gc-c gc-s" style="word-break:break-all">{{ feedback_url(doc.name) }}</div>
  {%- endif %}
</div>
